window.__finlexDocLoaded(10181,{"id":10181,"articles":[{"id":1000755,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Baseline template used by the US Treasury when negotiating bilateral income tax treaties, featuring the signature US 'Saving Clause', strict Limitation on Benefits (LOB) anti-treaty-shopping rules, and Special Tax Regime (STR) exclusions.","seq":0},{"id":1000756,"no":"Art. 1, 5, 10–12, 22 (LOB)","heading":"Saving Clause, Withholding Rates & Limitation on Benefits (LOB)","text":"• Saving Clause (Art. 1(4)): Preserves the US right to tax its own citizens and residents as if the treaty had not come into effect.\n• Limitation on Benefits — LOB (Art. 22): Objective tests (publicly traded, active trade or business, ownership/base-erosion, derivative benefits) preventing third-country treaty shopping.\n• Withholding Rates (Art. 10–12): Generally 5% (direct >=10% corporate) / 15% portfolio dividends, 0% interest, 0% royalties (subject to STR/expatriated entity exceptions).","seq":1},{"id":1000757,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Diverges from the OECD Model Tax Convention primarily through its strict objective LOB article (vs. OECD Principal Purpose Test — PPT) and citizenship-based Saving Clause.","seq":2},{"id":1000758,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (US Department of the Treasury): https://home.treasury.gov/policy-issues/tax-policy/treaties\nStatus: in_force.","seq":3}]});
